<script>(function(){var form=document.getElementById('photoForm');if(!form)return;
function shrink(file){return new Promise(function(ok){if(!/^image\/(jpe?g|png|webp)$/i.test(file.type)||!window.createImageBitmap||!window.DataTransfer)return ok(file);
createImageBitmap(file).then(function(bm){var m=1600,r=Math.min(1,m/Math.max(bm.width,bm.height)),c=document.createElement('canvas');c.width=Math.round(bm.width*r);c.height=Math.round(bm.height*r);c.getContext('2d').drawImage(bm,0,0,c.width,c.height);
c.toBlob(function(b){ok(b&&b.size<file.size?new File([b],(file.name||'photo').replace(/\.\w+$/,'')+'.jpg',{type:'image/jpeg'}):file);},'image/jpeg',0.85);}).catch(function(){ok(file);});});}
document.querySelectorAll('[data-photo-pick]').forEach(function(b){b.addEventListener('click',function(){document.getElementById(b.dataset.photoPick).click();});});
['photoCam','photoAlbum'].forEach(function(id){var inp=document.getElementById(id);inp.addEventListener('change',function(){if(!inp.files.length)return;
document.getElementById('photoBusy').classList.remove('d-none');form.querySelectorAll('button').forEach(function(x){x.disabled=true;});
Promise.all(Array.prototype.map.call(inp.files,shrink)).then(function(fs){try{var dt=new DataTransfer();fs.forEach(function(x){dt.items.add(x);});inp.files=dt.files;}catch(e){}form.submit();});});});})();</script><?php endif; ?>
